                face->uv[2].v = v1;
                face->uv[3].u = u1;
                face->uv[3].v = v1;
            }
        }
    }
}

replacements.text:
int segment = 0;
if (path->segment_count > 0) {
    do {
        column = 0;
        if (path->width_cells > 0) {
            float v0 = (float)(segment % 8) * 0.125f;
            float v1 = (float)(segment % 8 + 1) * 0.125f;
            do {
                int face_index = 0;
                int next_column = column + 1;
                float u0 = (float)column * 0.125f;
                float u1 = (float)(column + 1) * 0.125f;
                do {
                    if (face_index == 0) {
                        cRFaceQuad* face = &facequads[
                            face_index + 2 *
                                (column + segment * path->width_cells)];
                        face->header_word = 0;
                        face->vertex_0 = column + segment *
                            ((unsigned short)path->width_cells + 1);
                        face->vertex_1 = segment *
                            ((unsigned short)path->width_cells + 1) +
                            column + 1;
                        face->vertex_2 = (segment + 1) *
                            ((unsigned short)path->width_cells + 1) +
                            column + 1;
                        face->vertex_3 = column + (segment + 1) *
                            ((unsigned short)path->width_cells + 1);
                        if (!((column ^ segment) & 1)) {
                            face->texture_ref =
                                g_texture_refs.Add(texture_a, 0, 0);
                        } else {
                            face->texture_ref =
                                g_texture_refs.Add(texture_a, 0, 0);
                        }
                        face->uv[0].u = u0;
                        face->uv[0].v = v0;
                        face->uv[1].u = u1;
                        face->uv[1].v = v0;
                        face->uv[2].u = u1;
                        face->uv[2].v = v1;
                        face->uv[3].u = u0;
                        face->uv[3].v = v1;
                    } else {
                        cRFaceQuad* face = &facequads[
                            face_index + 2 *
                                (column + segment * path->width_cells)];
                        face->header_word = 0;
                        face->vertex_0 = segment *
                            ((unsigned short)path->width_cells + 1) +
                            column + 1;
                        face->vertex_1 = column + segment *
                            ((unsigned short)path->width_cells + 1);
                        face->vertex_2 = column + (segment + 1) *
                            ((unsigned short)path->width_cells + 1);
                        face->vertex_3 = (segment + 1) *
                            ((unsigned short)path->width_cells + 1) +
                            column + 1;
                        if (!((column ^ segment) & 1)) {
                            face->texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                        } else {
                            face->texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                        }
                        face->uv[0].u = u1;
                        face->uv[0].v = v0;
                        face->uv[1].u = u0;
                        face->uv[1].v = v0;
                        face->uv[2].u = u0;
                        face->uv[2].v = v1;
                        face->uv[3].u = u1;
                        face->uv[3].v = v1;
                    }
                    ++face_index;
                } while (face_index < 2);
                column = next_column;
            } while (column < path->width_cells);
        }
        ++segment;
    } while (segment < path->segment_count);
}
